function notificationId(parts){return 'NF-'+JSON.stringify(parts).split('').map(c=>c.charCodeAt(0).toString(16).padStart(4,'0')).join('')}
function notificationDateOffset(due,today){if(!validWorkDate(due)||!validWorkDate(today))return null;return Math.round((Date.parse(today+'T00:00:00Z')-Date.parse(due+'T00:00:00Z'))/86400000)}
