let db;try{db=JSON.parse(localStorage.getItem('kcc360-stage1'))||seed()}catch{db=seed()};let uid=localStorage.getItem('kcc360-user')||'s1',page='Overview',selected=null,tab='Overview',query='',filter='All';const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const user=()=>users.find(x=>x.id===uid)||users[0],staff=()=>['m1','m2','c1','d1','sa1','f1','fv1','dc1','da1','np1','na1','a1'].includes(uid),mine=p=>p.members.includes(uid),canSee=p=>['a1','c1','d1','sa1'].includes(uid)||p.mentor===uid||mine(p)||p.createdBy===uid&&['CREATED','PENDING_APPROVAL'].includes(p.state),owner=p=>p.owner===uid,mentor=p=>p.mentor===uid;const name=id=>users.find(x=>x.id===id)?.name||id;const label=s=>s.replaceAll('_',' ').toLowerCase().replace(/\b\w/g,c=>c.toUpperCase());function save(){localStorage.setItem('kcc360-stage1',JSON.stringify(db))}function log(p,action){let e={time:new Date().toISOString(),actor:name(uid),action,project:p?.id||'Workspace'};db.audit.unshift(e);if(p)p.history.unshift(e);save()}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}function pill(s){return `<span class="pill ${['COMPLETION_VERIFIED','CLOSED','ARCHIVED'].includes(s)?'green':['PENDING_APPROVAL','EVALUATION_PENDING'].includes(s)?'amber':''}">${esc(label(s))}</span>`}function btn(text,action,cls=''){return `<button class="${cls}" onclick="${action}">${text}</button>`}function go(p){page=p;selected=null;if(p==='Activity Intake')intakeFocus=null;render()}function openProject(id){selected=id;page='Projects';tab='Overview';render()}function visible(){return db.projects.filter(canSee)}function heading(title,desc,action=''){return `<div class="top"><div><div class="eyebrow">KCC360 / LEARNING WORKSPACE</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>${workspaceFreshness()}`}function modal(html){planXlsxCancel?.();planXlsxCancel=null;const dialog=$('#modal');dialog.innerHTML=html;const title=dialog.querySelector('h1,h2,h3,h4,h5,h6');dialog.removeAttribute('aria-label');dialog.removeAttribute('aria-labelledby');if(title){if(!title.id)title.id='modal-title';dialog.setAttribute('aria-labelledby',title.id)}else dialog.setAttribute('aria-label','Workspace dialog');dialog.showModal()}function closeModal(){planXlsxCancel?.();planXlsxCancel=null;$('#modal').close()}function pending(p){return (owner(p)&&['CREATED','APPROVED','STARTED','IN_PROGRESS','EXECUTION_COMPLETED','COMPLETION_VERIFIED'].includes(p.state))||(mentor(p)&&['PENDING_APPROVAL','EVALUATION_PENDING'].includes(p.state))||(mine(p)&&['REFLECTION_PENDING','EVALUATION_PENDING'].includes(p.state)&&!p.reflections[uid])}
function render(){initializeIntakeRepresentatives();db.activityIntakes??=[];initializeClubs();initializeMembershipHistory();initializeClubControls();initializeMentorTransfers();initializeAcademicProgression();db.clubEvaluations??=[];let placement=db.academicProfiles[uid];$('.scope').textContent=placement?.programme?placement.programme+' · '+placement.period+' · '+placement.year+' · '+placement.academicYear:placement?'KCC · Academic placement not mapped':'KCC · Shared learning workspace';initializeNotifications();if(typeof initializeGovernance==='function')initializeGovernance();if(typeof initializeRubrics==='function')initializeRubrics();const nav=['Overview','Activity Intake','Projects','Action Centre','Notifications','My Portfolio','Performance','Development','Academic Progression','Activity Changes','Club Evaluation','Certificates','Notices','Academic Plans','Clubs','Club Finance','My Documents','Reports','Assessment Settings','Mentor Assignments','SRS Coverage','Audit & Demo'];$('#nav').innerHTML=nav.map((n,i)=>`<button class="${page===n?'active':''}" onclick="go('${n}');${n==='Notifications'?'refreshNotifications()':''}">${['◈','↳','▤','◷','◉','◇','◈','↗','⇧','↻','⚑','▧','◉','▦','♧','¤','▣','▥','⚖','⇄','✓','⚙'][i]} &nbsp; ${n}</button>`).join('');$('#crumb').textContent=page.toUpperCase();$('#user').innerHTML=users.map(u=>`<option value="${u.id}" ${u.id===uid?'selected':''}>${u.name} · ${u.role}</option>`).join('');$('#app').innerHTML=selected?detail():({Overview:overview,'Activity Intake':activityIntakesPage,Projects:projects,'Action Centre':actions,'Notifications':notificationsPage,'My Portfolio':portfolio,Performance:performancePage,Development:developmentPage,'Academic Progression':academicProgressionPage,'Activity Changes':activityChangesPage,'Club Evaluation':clubEvaluationPage,Certificates:certificates,Notices:communicationPage,'Academic Plans':plansPage,'Clubs':clubsPage,'Club Finance':financePage,'My Documents':documentsPage,Reports:reportsPage,'Assessment Settings':assessmentSettings,'Mentor Assignments':mentorAssignmentPage,'SRS Coverage':coveragePage,'Audit & Demo':audit}[page])()}
$('#user').onchange=e=>{uid=e.target.value;localStorage.setItem('kcc360-user',uid);selected=null;render();toast('Demo account changed')};
