function clubVolunteerRows(){return typeof sharedReady!=='undefined'&&sharedReady?db.clubVolunteerOpenings||[]:db.projects.map(clubVolunteerProjection).filter(Boolean)}
function clubVolunteerApplicationForm(eventId){const r=clubVolunteerRows().find(r=>r.eventId===eventId);if(!r?.canApply)return toast('This opening is unavailable for a new application.');modal(`<h2>Apply for a volunteer position</h2><p>${esc(r.title)} · Closing ${esc(r.deadline)} (Nepal time). One pending position choice per student; selection is not guaranteed.</p><form onsubmit="applyClubVolunteerPosition(event,'${r.eventId}',${r.openingVersion},${r.ownApplication?.revision||0})"><label>Position<select name="positionId">${r.positions.map(v=>`<option value="${esc(v.id)}">${esc(v.domain)} · ${esc(v.title)} (${v.capacity} requested)</option>`).join('')}</select></label><label>Your expected contribution<textarea name="motivation" required maxlength="1500"></textarea></label><label><input type="checkbox" name="confirm" value="yes" required> I want to volunteer and understand this is an application.</label><button type="submit">Submit my application</button></form>`)}
function clubVolunteerOpeningsPanel(){const rows=clubVolunteerRows();if(!rows.length)return '';return `<section class="panel"><h2>Club volunteer openings & my applications</h2><p>Applications are separate from club membership and event enrolment. Only the organizing club's active general members may apply.</p>${rows.map(r=>`<article class="card"><h3>${esc(r.title)}</h3><p>${esc(r.clubTitle)} · Closing ${esc(r.deadline)} (Nepal time)</p>${tableHTML(['Domain','Position','Requested capacity','Expected contribution'],r.positions.map(v=>[esc(v.domain),esc(v.title),v.capacity,esc(v.contribution)]))}${r.ownApplication?`<p>My application: ${esc(r.ownApplication.state)} · ${esc(r.ownApplication.positionId)}</p><p>${esc(r.ownApplication.motivation)}</p>${r.ownApplication.review?`<p>Review feedback: ${esc(r.ownApplication.review.reason)}</p>`:''}`:''}<div class="buttons">${r.canApply?btn(r.ownApplication?'Apply again':'Apply for a position',`clubVolunteerApplicationForm('${r.eventId}')`):''}${r.ownApplication?.state==='APPLIED'?btn('Withdraw my application',`withdrawClubVolunteerApplication('${r.eventId}',${r.openingVersion},${r.ownApplication.revision})`):''}</div></article>`).join('')}</section>`}
const clubVolunteerPreviousClubs=clubsPage;clubsPage=function(){return clubVolunteerPreviousClubs()+clubVolunteerOpeningsPanel()};
const clubVolunteerPreviousPlanPanel=clubRecruitmentPlanPanel;clubRecruitmentPlanPanel=function(p){return clubVolunteerPreviousPlanPanel(p)+(clubRecruitmentPlanWritable(p)&&clubRecruitmentPlanLatest(p)&&!p.clubVolunteerOpening?`<section class="panel"><h3>Open member-only applications</h3>${btn('Review & open applications','clubVolunteerOpenForm()')}</section>`:p?.clubVolunteerOpening&&clubRecruitmentPlanReader(p)?`<section class="panel"><h3>Volunteer application opening</h3><p>Position draft v${p.clubVolunteerOpening.planVersion} frozen · Closes ${esc(p.clubVolunteerOpening.deadline)} (Nepal time). ${clubVolunteerOpeningCurrent(p)?'Current source':'Source changed or event unavailable; new applications blocked.'}</p><p>Selection is recorded separately; use the controlled roster handoff below. Targeted in-app notices use current source eligibility.</p></section>`:'')};
function clubVolunteerReviewWriter(p,a){const c=p?.sourceClub&&clubById(p.sourceClub);return !!c&&clubRecruitmentPlanReader(p)&&(manageClub(c)||owner(p)&&clubMember(c))&&clubVolunteerOpeningCurrent(p)&&(!a||a.student!==uid&&!clubVolunteerHandedOff(p,a))&&!participantResolution(p,uid)}
function clubVolunteerSelectedCount(p,positionId){return (p.clubVolunteerApplications||[]).filter(a=>a.openingVersion===p.clubVolunteerOpening?.version&&a.positionId===positionId&&a.state==='SELECTED').length}
function clubVolunteerReviewForm(applicationId){const p=current(),a=p?.clubVolunteerApplications?.find(a=>a.id===applicationId),o=p?.clubVolunteerOpening;if(!a||!clubVolunteerReviewWriter(p,a)||!['APPLIED','SELECTED','NOT_SELECTED'].includes(a.state))return toast('Current independent organizer review required.');const position=o.positions.find(r=>r.id===a.positionId);modal(`<h2>Review volunteer application</h2><p>${esc(name(a.student))} · ${esc(position?.domain)} · ${esc(position?.title)}</p><p>${esc(a.motivation)}</p><p>Selected for this position: ${clubVolunteerSelectedCount(p,a.positionId)} / ${position?.capacity||0}. Selection does not enrol or assign work.</p><form onsubmit="reviewClubVolunteerApplication(event,'${a.id}',${o.version},${a.revision})"><label>Decision<select name="decision">${a.state==='APPLIED'?'<option value="SELECTED">Select within capacity</option><option value="NOT_SELECTED">Not selected</option>':'<option value="RETURN_TO_PENDING">Return for fresh review (releases selection)</option>'}</select></label><label>Reason / feedback shared with this applicant<textarea name="reason" required maxlength="1000"></textarea></label><label><input type="checkbox" name="confirm" value="yes" required> I confirm this decision and have reviewed capacity.</label><button type="submit">Record decision</button></form>`)}
function reviewClubVolunteerApplication(event,applicationId,openingVersion,expectedRevision){event.preventDefault();const p=current(),matches=(p?.clubVolunteerApplications||[]).filter(a=>a.id===applicationId),a=matches.length===1?matches[0]:null,o=p?.clubVolunteerOpening,f=Object.fromEntries(new FormData(event.target));if(!a||!clubVolunteerReviewWriter(p,a)||clubVolunteerOwn(p,a.student)!==a||o.version!==openingVersion||!Number.isSafeInteger(expectedRevision)||a.revision!==expectedRevision||Object.keys(f).some(k=>!['decision','reason','confirm'].includes(k))||f.confirm!=='yes'||typeof f.reason!=='string'||!f.reason.trim()||f.reason.trim().length>1000)return toast('Current independent organizer, application version, confirmation and reason required.');const decision=f.decision,prior=a.state;if(!(prior==='APPLIED'&&['SELECTED','NOT_SELECTED'].includes(decision)||['SELECTED','NOT_SELECTED'].includes(prior)&&decision==='RETURN_TO_PENDING'))return toast('Use a current application or return a prior decision for fresh review.');
 if(decision==='SELECTED'){const position=o.positions.find(r=>r.id===a.positionId);if(!clubVolunteerEligible(p,a.student)||!position||!Number.isSafeInteger(position.capacity)||position.capacity<1||clubVolunteerSelectedCount(p,a.positionId)>=position.capacity)return toast('Applicant must remain an active general member and the position must have capacity.');}
 const at=new Date().toISOString(),state=decision==='RETURN_TO_PENDING'?'APPLIED':decision,reason=f.reason.trim();a.state=state;a.revision++;a.updatedAt=at;a.review={state,reason,by:uid,at};a.history.push({state,decision,priorState:prior,reason,by:uid,at,revision:a.revision});log(p,'Volunteer application review recorded: '+decision);closeModal();render();toast('Review recorded. Event roster and tasks remain unchanged.')}
function clubVolunteerSelectionPanel(p){if(!p?.clubVolunteerOpening||!clubRecruitmentPlanReader(p))return '';const o=p.clubVolunteerOpening,rows=(p.clubVolunteerApplications||[]).filter(a=>a.openingVersion===o.version);return `<section class="panel"><h2>Volunteer application review & selection</h2><p>Only current club/event organizers decide. No one can decide their own application. Mentor and Student Affairs retain read access. Selection is separate from enrolment, task delegation and verified achievement.</p>${tableHTML(['Domain / position','Capacity','Selected','Pending'],o.positions.map(r=>[esc(r.domain+' / '+r.title),r.capacity,clubVolunteerSelectedCount(p,r.id),rows.filter(a=>a.positionId===r.id&&a.state==='APPLIED').length]))}${!clubVolunteerOpeningCurrent(p)?'<p>Source or event changed. Decisions are unavailable until the source is resolved.</p>':''}${rows.map(a=>{const r=o.positions.find(r=>r.id===a.positionId);return `<article class="card"><h3>${esc(name(a.student))} · ${esc(r?.title||a.positionId)}</h3><p>${esc(a.state)} · Application revision ${a.revision}</p><p>${esc(a.motivation)}</p>${a.review?`<p>Latest decision: ${esc(a.review.state)} · ${esc(a.review.reason)} · ${esc(name(a.review.by))}</p>`:''}${clubVolunteerReviewWriter(p,a)&&['APPLIED','SELECTED','NOT_SELECTED'].includes(a.state)?btn(a.state==='APPLIED'?'Review application':'Return for fresh review',`clubVolunteerReviewForm('${a.id}')`):''}${a.student===uid&&['APPLIED','SELECTED','NOT_SELECTED'].includes(a.state)?'<p>Your application requires another existing authorized club/event organizer.</p>':''}<details><summary>Application / decision history</summary>${a.history.map(h=>`<p>${esc(h.state)} · ${esc(name(h.by))} · ${esc(eventTime(h.at))}${h.reason?' · '+esc(h.reason):''}</p>`).join('')}</details></article>`}).join('')||'<p>No applications received.</p>'}</section>`}
const clubVolunteerSelectionPreviousOverview=projectOverview;projectOverview=function(p){return clubVolunteerSelectionPreviousOverview(p)+clubVolunteerSelectionPanel(p)};

function clubVolunteerHandedOff(p,a){return !!a&&(p?.clubVolunteerHandoffs||[]).some(h=>h.openingVersion===a.openingVersion&&h.entries.some(e=>e.applicationId===a.id))}
function clubVolunteerHandoffPreview(p){const o=p?.clubVolunteerOpening,all=(p?.clubVolunteerApplications||[]).filter(a=>a.openingVersion===o?.version&&a.state==='SELECTED'),rows=all.filter(a=>!clubVolunteerHandedOff(p,a)),errors=[];if(!clubVolunteerOpeningCurrent(p))errors.push('Source or event is unavailable.');if(new Set(p?.members||[]).size!==(p?.members||[]).length)errors.push('Existing roster has duplicate entries.');for(const a of rows){const positions=o.positions.filter(r=>r.id===a.positionId),r=positions[0];if(clubVolunteerOwn(p,a.student)!==a||(p.clubVolunteerApplications||[]).filter(v=>v.id===a.id).length!==1||!Number.isSafeInteger(a.revision))errors.push('Application identity or revision needs review.');if(!clubVolunteerEligible(p,a.student))errors.push(name(a.student)+': active general membership required.');if(participantResolution(p,a.student))errors.push(name(a.student)+': existing participant outcome requires the participant process.');if(positions.length!==1||!Number.isSafeInteger(r.capacity)||r.capacity<1||clubVolunteerSelectedCount(p,a.positionId)>r.capacity)errors.push('Position or selection capacity needs review.');}const basis=JSON.stringify({openingVersion:o?.version,handoffVersion:p?.clubVolunteerHandoffs?.length||0,roster:p?.members||[],rows:rows.map(a=>[a.id,a.student,a.revision,a.positionId])});return {rows,errors,basis,added:rows.filter(a=>!p.members.includes(a.student)).length,pending:(p?.clubVolunteerApplications||[]).filter(a=>a.openingVersion===o?.version&&a.state==='APPLIED').length}}
function clubVolunteerHandoffForm(){const p=current();if(!clubVolunteerReviewWriter(p))return toast('Current organizer required.');const v=clubVolunteerHandoffPreview(p);if(!v.rows.length||v.errors.length)return toast(v.errors.join(' ')||'No new selections to hand off.');modal(`<h2>Confirm selected-volunteer roster handoff</h2><p>${v.rows.length} selections: ${v.added} students to add; ${v.rows.length-v.added} already enrolled. All ${p.members.length} existing roster entries and their records are preserved. ${v.pending} applications remain pending and are not enrolled by this action.</p>${tableHTML(['Student','Position','Roster'],v.rows.map(a=>[esc(name(a.student)),esc(p.clubVolunteerOpening.positions.find(r=>r.id===a.positionId)?.title),p.members.includes(a.student)?'Already enrolled':'Will be added']))}<form onsubmit="handoffClubVolunteers(event)"><input type="hidden" name="basis" value="${esc(v.basis)}"><label>Reason<textarea name="reason" required maxlength="1000"></textarea></label><label><input type="checkbox" name="confirm" value="yes" required> Confirm this complete selected roster. Later participant changes use the existing participant process.</label><button type="submit">Confirm roster handoff</button></form>`)}
function handoffClubVolunteers(event){event.preventDefault();const p=current(),f=Object.fromEntries(new FormData(event.target));if(!clubVolunteerReviewWriter(p))return toast('Current organizer required.');const v=clubVolunteerHandoffPreview(p);if(!v.rows.length||v.errors.length||Object.keys(f).some(k=>!['basis','reason','confirm'].includes(k))||f.basis!==v.basis||f.confirm!=='yes'||typeof f.reason!=='string'||!f.reason.trim()||f.reason.trim().length>1000)return toast('Refresh the roster preview; current selections, membership, capacity, reason and confirmation are required.');const entries=v.rows.map(a=>({applicationId:a.id,applicationRevision:a.revision,student:a.student,positionId:a.positionId,added:!p.members.includes(a.student)})),at=new Date().toISOString();p.members.push(...entries.filter(e=>e.added).map(e=>e.student));p.clubVolunteerHandoffs??=[];p.clubVolunteerHandoffs.push({version:p.clubVolunteerHandoffs.length+1,openingVersion:p.clubVolunteerOpening.version,entries,by:uid,at,reason:f.reason.trim()});log(p,'Selected-volunteer roster handoff: '+entries.length+' selections, '+v.added+' added');closeModal();render();toast('Roster handoff saved. Existing records retained; tasks and achievements require their normal workflows.')}
function clubVolunteerHandoffPanel(p){if(!p?.clubVolunteerOpening||!clubRecruitmentPlanReader(p))return '';const v=clubVolunteerHandoffPreview(p);return `<section class="panel"><h2>Selected-volunteer roster handoff</h2><p>${v.rows.length} selections awaiting handoff · ${v.added} students to add · ${p.members.length} existing roster entries preserved · ${v.pending} pending applications.</p><p>Handed-off decisions are retained. Use existing participant controls for subsequent withdrawals or outcomes. No tasks, evaluations or achievements are created by enrolment.</p>${v.errors.map(e=>`<p>${esc(e)}</p>`).join('')}${clubVolunteerReviewWriter(p)&&v.rows.length&&!v.errors.length?btn('Preview & confirm roster handoff','clubVolunteerHandoffForm()'):''}${(p.clubVolunteerHandoffs||[]).map(h=>`<details><summary>Handoff v${h.version} · ${h.entries.length} selections · ${esc(eventTime(h.at))}</summary><p>${esc(name(h.by))} · ${esc(h.reason)}</p>${tableHTML(['Student','Position reference','Action'],h.entries.map(e=>[esc(name(e.student)),esc(e.positionId),e.added?'Added':'Already enrolled']))}</details>`).join('')}</section>`}
const clubVolunteerHandoffPreviousOverview=projectOverview;projectOverview=function(p){return clubVolunteerHandoffPreviousOverview(p)+clubVolunteerHandoffPanel(p)};

function clubVolunteerDomains(p){const seen=new Set();return (p?.clubVolunteerOpening?.positions||[]).filter(r=>{const k=r.domain.trim().toLowerCase();if(seen.has(k))return false;seen.add(k);return true}).map(r=>({id:r.id,title:r.domain}))}
function clubVolunteerDomainPosition(p,domainId,positionId){const domain=clubVolunteerDomains(p).find(d=>d.id===domainId),position=p?.clubVolunteerOpening?.positions.find(r=>r.id===positionId);return !!domain&&!!position&&domain.title.trim().toLowerCase()===position.domain.trim().toLowerCase()}
function clubVolunteerDomainSourceCurrent(p){return clubVolunteerOpeningCurrent(p,['APPROVED','STARTED','IN_PROGRESS'])}
function clubVolunteerDomainRoster(p,domainId){if(!clubVolunteerDomainSourceCurrent(p))return [];return (p.clubVolunteerApplications||[]).filter(a=>a.state==='SELECTED'&&a.openingVersion===p.clubVolunteerOpening.version&&clubVolunteerOwn(p,a.student)===a&&clubVolunteerHandedOff(p,a)&&clubVolunteerDomainPosition(p,domainId,a.positionId)&&clubVolunteerEligible(p,a.student)&&activeParticipant(p,a.student)).map(a=>a.student)}
function clubVolunteerDomainLatest(p,domainId){const rows=(p?.clubVolunteerDomainLeads||[]).filter(r=>r.domainId===domainId);return rows.length===1?rows[0].versions.at(-1):null}
function clubVolunteerDomainLeadCurrent(p,domainId){const v=clubVolunteerDomainLatest(p,domainId);return !!v&&v.state==='ACTIVE'&&v.openingVersion===p.clubVolunteerOpening?.version&&clubVolunteerDomainRoster(p,domainId).includes(v.student)}
function clubVolunteerDomainManager(p){const c=p?.sourceClub&&clubById(p.sourceClub);return !!c&&canSee(p)&&clubVolunteerDomainSourceCurrent(p)&&((owner(p)&&clubMember(c)&&activeParticipant(p,uid))||mentor(p)&&!participantResolution(p,uid))}
function clubVolunteerDomainSummary(p){return clubVolunteerDomains(p).map(d=>{const v=clubVolunteerDomainLatest(p,d.id);return {domainId:d.id,title:d.title,student:v?.student||null,version:v?.version||0,state:v?.state||'UNASSIGNED',current:clubVolunteerDomainLeadCurrent(p,d.id)}})}
function clubVolunteerDomainLeadForm(domainId){const p=current(),domain=clubVolunteerDomains(p).find(d=>d.id===domainId),v=clubVolunteerDomainLatest(p,domainId);if(!domain||!clubVolunteerDomainManager(p))return toast('Current event lead or assigned mentor required.');const roster=clubVolunteerDomainRoster(p,domainId);modal(`<h2>Appoint / replace domain lead</h2><p>${esc(domain.title)} · Only selected volunteers already handed into this domain and still active can be appointed. This coordinates the domain; mentor verification and wider event authority remain unchanged.</p><form onsubmit="saveClubVolunteerDomainLead(event,'${domain.id}',${v?.version||0})"><label>Domain lead<select name="student"><option value="">End current appointment</option>${roster.map(id=>`<option value="${esc(id)}" ${v?.student===id?'selected':''}>${esc(name(id))}</option>`).join('')}</select></label><label>Reason<textarea name="reason" required maxlength="1000"></textarea></label><label><input type="checkbox" name="confirm" value="yes" required> Confirm this domain appointment change.</label><button type="submit">Save appointment</button></form>`)}
function saveClubVolunteerDomainLead(event,domainId,expectedVersion){event.preventDefault();const p=current(),domain=clubVolunteerDomains(p).find(d=>d.id===domainId),v=clubVolunteerDomainLatest(p,domainId),f=Object.fromEntries(new FormData(event.target));if(!domain||!clubVolunteerDomainManager(p)||!Number.isSafeInteger(expectedVersion)||expectedVersion!==(v?.version||0)||Object.keys(f).some(k=>!['student','reason','confirm'].includes(k))||typeof f.student!=='string'||f.confirm!=='yes'||typeof f.reason!=='string'||!f.reason.trim()||f.reason.trim().length>1000||(p.clubVolunteerDomainLeads||[]).filter(r=>r.domainId===domainId).length>1)return toast('Current authority, domain, appointment revision, reason and confirmation required.');if(f.student?!clubVolunteerDomainRoster(p,domainId).includes(f.student)||v?.state==='ACTIVE'&&v.student===f.student:!v||v.state!=='ACTIVE')return toast('Choose another active selected volunteer in this domain or end an active appointment.');p.clubVolunteerDomainLeads??=[];let record=p.clubVolunteerDomainLeads.find(r=>r.domainId===domainId);if(!record){record={domainId,versions:[]};p.clubVolunteerDomainLeads.push(record)}record.versions.push({version:(v?.version||0)+1,openingVersion:p.clubVolunteerOpening.version,student:f.student||null,state:f.student?'ACTIVE':'ENDED',by:uid,at:new Date().toISOString(),reason:f.reason.trim()});log(p,'Volunteer domain lead '+(f.student?'appointed':'ended')+': '+domain.title);closeModal();render();toast('Domain appointment saved; historical records and existing task/review authority retained.')}
function clubVolunteerDomainPanel(p){if(!p?.clubVolunteerOpening&&!p?.clubVolunteerDomainSummary||!canSee(p))return '';const rows=p.clubVolunteerDomainSummary||clubVolunteerDomainSummary(p),manager=clubVolunteerDomainManager(p);if(!rows.length)return '';return `<section class="panel"><h2>Volunteer domain leads</h2><p>Domain leads coordinate selected, enrolled volunteers. Individual tasks and progress use the existing task workflow; mentor verification remains separate. Current domain leads can assign scoped responsibilities and monitor them below.</p>${rows.map(d=>`<article class="card"><h3>${esc(d.title)}</h3><p>${d.student?esc(name(d.student)):'No lead appointed'} · ${d.current?'Current appointment':d.state==='ACTIVE'?'Eligibility or source changed; appointment inactive':esc(d.state)} · v${d.version}</p>${manager?btn('Appoint / replace / end',`clubVolunteerDomainLeadForm('${d.domainId}')`):''}${clubRecruitmentPlanReader(p)?`<details><summary>Appointment history</summary>${((p.clubVolunteerDomainLeads||[]).find(r=>r.domainId===d.domainId)?.versions||[]).map(v=>`<p>v${v.version} · ${esc(v.state)} · ${v.student?esc(name(v.student)):'No lead'} · ${esc(name(v.by))} · ${esc(eventTime(v.at))} · ${esc(v.reason)}</p>`).join('')||'<p>No appointment history.</p>'}</details>`:''}</article>`).join('')}</section>`}
const clubVolunteerDomainPreviousOverview=projectOverview;projectOverview=function(p){return clubVolunteerDomainPreviousOverview(p)+clubVolunteerDomainPanel(p)};

function clubVolunteerDomainTaskAuthority(p,domainId){const v=clubVolunteerDomainLatest(p,domainId);return canSee(p)&&clubVolunteerDomainLeadCurrent(p,domainId)&&v.student===uid}
function clubVolunteerDomainTaskContext(p){return clubVolunteerDomains(p).map(d=>({domainId:d.id,title:d.title,sourceCurrent:clubVolunteerDomainSourceCurrent(p),leadVersion:clubVolunteerDomainLatest(p,d.id)?.version||0,canAssign:clubVolunteerDomainTaskAuthority(p,d.id),assignees:clubVolunteerDomainTaskAuthority(p,d.id)?clubVolunteerDomainRoster(p,d.id):[]}))}
