function mentorEvaluationCurrent(p,student){return mentorRecordSourceCurrent(p)&&['REFLECTION_PENDING','EVALUATION_PENDING'].includes(p.state)&&activeParticipant(p,student)&&p.mentor!==student&&!!p.reflections[student]&&!p.evaluations[student]?.final&&deliveryIndividualReady(p,student)}
function mentorEvaluationCurrentSource(n,d){if(d.invalid||n.group!=='PROJECT'||n.route!=='Projects')return null;const p=db.projects.find(p=>p.id===n.sourceId);if(!mentorEvaluationCurrent(p,d.student))return null;const version=p.reflections[d.student].version||1,due=validWorkDate(p.due)?p.due:null;if(n.due!==due)return null;if(n.base){const base=JSON.stringify(['PROJECT',p.id,d.key,version,p.mentor]);if(n.base!==base||n.sourceVersion!==version||n.id!==notificationId([base,n.phase,n.recipient,n.due]))return null}else if(n.recipient!==p.mentor||n.version!==version)return null;return p}
const mentorRecordPreviousNotificationActions=notificationActions;notificationActions=function(today=localDay()){return mentorRecordPreviousNotificationActions(today).filter(a=>{const d=mentorEvaluationDescriptor(a);return !d||!!mentorEvaluationCurrentSource(a,d)})};
const mentorRecordPreviousNotificationAccess=notificationAccess;notificationAccess=function(n,actor=uid){const d=mentorEvaluationDescriptor(n);if(!d)return mentorRecordPreviousNotificationAccess(n,actor);const p=mentorEvaluationCurrentSource(n,d);if(!p||n.recipient!==actor)return false;const phase=n.phase||'ACTION',recipient=['ACTION','REMINDER','OVERDUE'].includes(phase)?p.mentor:({SUPERVISOR_ESCALATION:'c1',COORDINATOR_ESCALATION:'d1',ADMINISTRATIVE_ESCALATION:'a1'})[phase];return actor===recipient&&mentorRecordPreviousNotificationAccess(n,actor)};
