function mentorRecordReviewPanel(){const rows=mentorRecordReviewActions();if(!rows.length)return '';return `<section class="panel"><h2>Your evidence & contribution reviews</h2><p>Review submitted attendance rosters, current evidence and submitted individual claims in their existing workflows. A pending claim is not verified time; its supporting evidence and the existing individual/day limits still apply.</p>${rows.map(a=>`<article class="card"><h3>${esc(a.title)}</h3><p>${esc(db.projects.find(p=>p.id===a.sourceId)?.title||a.sourceId)}</p>${btn('Open Projects overview',"go('Projects')")}${btn('Open assigned action queue',"go('Action Centre')")}</article>`).join('')}</section>`}
