function deliveryReviewDescriptor(n){let key=n?.key;if(n?.base){try{key=JSON.parse(n.base)[2]}catch{return null}}return key==='delivery-plan'||typeof key==='string'&&key.startsWith('delivery:')?{key}:null}
function deliveryReviewCurrentSource(n,d){if(n.group!=='PROJECT'||n.route!=='Projects')return null;const p=db.projects.find(p=>p.id===n.sourceId);if(!mentorRecordSourceCurrent(p)||!deliveryManaged(p))return null;let version;if(d.key==='delivery-plan'){const v=p.deliveryPlan;if(!v||v.state!=='SUBMITTED'||v.by===p.mentor||!['CREATED','PENDING_APPROVAL','APPROVED'].includes(p.state))return null;version=v.version}else{if(!['STARTED','IN_PROGRESS','EXECUTION_COMPLETED','REFLECTION_PENDING','EVALUATION_PENDING'].includes(p.state))return null;const s=(p.deliverySubmissions||[]).find(s=>d.key==='delivery:'+s.student+':'+s.kind);if(!s||s.state!=='SUBMITTED'||s.student===p.mentor)return null;version=s.version}const due=validWorkDate(p.due)?p.due:null;if(n.due!==due)return null;if(n.base){const base=JSON.stringify(['PROJECT',p.id,d.key,version,p.mentor]);if(n.base!==base||n.sourceVersion!==version||n.id!==notificationId([base,n.phase,n.recipient,n.due]))return null}else if(n.recipient!==p.mentor||n.version!==version)return null;return p}
