const deliveryReviewPreviousAccess=notificationAccess;notificationAccess=function(n,actor=uid){const d=deliveryReviewDescriptor(n);if(!d)return deliveryReviewPreviousAccess(n,actor);const p=deliveryReviewCurrentSource(n,d);if(!p||n.recipient!==actor)return false;const recipient=['ACTION','REMINDER','OVERDUE'].includes(n.phase||'ACTION')?p.mentor:({SUPERVISOR_ESCALATION:'c1',COORDINATOR_ESCALATION:'d1',ADMINISTRATIVE_ESCALATION:'a1'})[n.phase];return actor===recipient&&deliveryReviewPreviousAccess(n,actor)};

// Creation-only enrolment choice; legacy events and existing participant controls are retained.
function clubEventEnrolmentSource(id,pid,iid){const c=clubById(id),p=c&&clubPlan(c,pid),i=p&&clubItems(p).find(i=>i.id===iid);if(!c||!p||!i||!manageClub(c)||c.state!=='ACTIVE'||!isApprovedClubPlan(p)||!latestApprovedRevision(c,p)||i.status==='CANCELLED'||!clubMember(c,i.lead))return null;return {c,p,i,basis:JSON.stringify({club:id,plan:pid,version:p.version||1,item:i,mentor:c.mentor,activeMembers:c.members.filter(m=>m.state==='ACTIVE').map(m=>m.user)})}}
