const clubEventEnrolmentPreviousCreate=clubEvent;clubEvent=function(id,pid,iid,mode,basis){const c=clubById(id),p=c&&clubPlan(c,pid),item=p&&clubItems(p).find(i=>i.id===(iid||clubItems(p)[0]?.id));if(!item)return toast('Activity row unavailable.');const s=clubEventEnrolmentSource(id,pid,item.id);if(!s)return toast('Use the latest approved activity and authorized organizer.');if(mode!==undefined&&(!['ALL_ACTIVE_MEMBERS','SELECTED_VOLUNTEERS'].includes(mode)||basis!==s.basis))return toast('Refresh the event preview and confirm a current enrolment choice.');const existing=clubItemActivity(item);if(existing)return openProject(existing.id);mode??='ALL_ACTIVE_MEMBERS';if(mode==='ALL_ACTIVE_MEMBERS'){clubEventEnrolmentPreviousCreate(id,pid,item.id);const event=clubItemActivity(item);if(event){event.clubEventEnrolment={mode,by:uid,at:new Date().toISOString(),leadAtCreation:item.lead};log(event,'Event enrolment confirmed: all active club members');closeModal();render()}return}const event={id:clubKey('CE'),title:item.title,description:item.output,programme:'Cross-programme club activity',type:'Club event (project workspace)',state:'APPROVED',owner:item.lead,mentor:c.mentor,members:[item.lead],due:item.end,sdg:item.sdg,tasks:[],evidence:[],reflections:{},evaluations:{},certs:{},published:{},messages:[],history:[],sourceClub:id,clubPlanItem:item.id,clubPlanId:p.id,clubMetadata:JSON.parse(JSON.stringify(item)),clubEventEnrolment:{mode,by:uid,at:new Date().toISOString(),leadAtCreation:item.lead}};db.projects.push(event);log(event,'Created selected-volunteer event from approved plan '+p.id+' / '+item.id);clubLog(c,'Activity row '+item.id+' generated selected-volunteer event '+event.id);closeModal();render();toast('Event created with its student lead. Recruit and confirm selected volunteers before assigning their work.')};
