// Linked institutional team drafts are historical/read-only until controlled execution is connected.
function teamActivityProtectedSnapshot(){const ids=new Set(db.projects.filter(p=>p.teamIntakeProvenance).map(p=>p.id));return JSON.stringify({projects:db.projects.filter(p=>ids.has(p.id)),intakes:(db.activityIntakes||[]).filter(r=>r.teamHandoff||ids.has(r.projectId))})}
function teamActivityCommandReference(args,context){const ids=new Set(db.projects.filter(p=>p.teamIntakeProvenance).map(p=>p.id));for(const r of db.activityIntakes||[])if(r.teamHandoff||ids.has(r.projectId))ids.add(r.id);const inspect=v=>typeof v==='string'?ids.has(v):v&&typeof v==='object'?Object.values(v).some(inspect):false;return inspect(args)||inspect(context)}
const teamActivityPriorCanEdit=proposalCanEdit;proposalCanEdit=function(p){return !p?.teamIntakeProvenance&&teamActivityPriorCanEdit(p)};
const teamActivityPriorCanSubmit=proposalCanSubmit;proposalCanSubmit=function(p){return !p?.teamIntakeProvenance&&teamActivityPriorCanSubmit(p)};
const teamActivityPriorApprover=proposalApprover;proposalApprover=function(p){return !p?.teamIntakeProvenance&&teamActivityPriorApprover(p)};
const teamActivityPriorAdvance=advance;advance=function(next){if(current()?.teamIntakeProvenance)return toast('This institutional team draft requires its controlled activity workflow. Permission to start is separate.');return teamActivityPriorAdvance(next)};
const teamActivityPriorOverview=projectOverview;projectOverview=function(p){if(!p?.teamIntakeProvenance)return teamActivityPriorOverview(p);return `<h2>Linked team activity</h2><p>${esc(p.title)} · ${esc(label(p.state))}</p><p>${esc(p.description)}</p><p>Programme: ${esc(p.programme)} · Type: ${esc(p.type)} · Due: ${esc(p.due)}</p><h3>Confirmed team</h3>${tableHTML(['Student account','Responsibility'],p.members.map(id=>[esc(name(id)),id===p.owner?'Team lead':'Member']))}<p>Assigned mentor: ${esc(name(p.mentor))}</p><p>The final-approved intake and its history are preserved. ${p.state==='STARTED'?'Start is recorded. Further task tracking requires the controlled activity workflow.':'This draft is read-only. Editing, submission, approval and permission to start require the controlled activity workflow.'}</p>`};

// Department-led class workshops/seminars only. Uses shared CSV parsing, task
// mapping, command persistence and existing owner-restricted demo authority.
const departmentTaskCSVColumns=['externalId','studentReference','title','due','expectedOutput','responsibility','evidenceRequirement','groupReference','conceptCriterion','skillsCriterion','leadershipCriterion','impactCriterion'];
const departmentTaskCSVDomains={conceptCriterion:'CONCEPT',skillsCriterion:'SKILLS',leadershipCriterion:'LEADERSHIP',impactCriterion:'SDG_IMPACT'};
function departmentTaskCSVSource(p){
 if(!p||p.sourceClub||p.intakeProvenance||p.teamIntakeProvenance||p.specialActivity||!['APPROVED','STARTED','IN_PROGRESS'].includes(p.state)||!activityControlActive(p))return null;
 const plans=db.plans.filter(x=>x.id===p.sourcePlan),plan=plans.length===1?plans[0]:null,item=plan?.items.find(i=>i.id===p.sourceItem);
 if(!plan||!['APPROVED','IN_PROGRESS','COMPLETED'].includes(plan.state)||!item||!['Workshop','Seminar'].includes(item.type)||p.type!==item.type||db.plans.some(x=>x.family===plan.family&&x.version>plan.version&&['APPROVED','IN_PROGRESS','COMPLETED'].includes(x.state))||!plan.department||!plan.course||!plan.semester||!p.members.length||new Set(p.members).size!==p.members.length)return null;
 if((db.activityChanges||[]).some(r=>r.projectId===p.id&&activityChangesPending(r)))return null;
 const roster=[...p.members].sort().map(student=>({student,active:activeParticipant(p,student)}));
 return {plan,item,roster,basis:JSON.stringify({projectId:p.id,sourcePlan:plan.id,sourceVersion:plan.version,department:plan.department,course:plan.course,semester:plan.semester,programme:plan.programme,batch:plan.batch,year:plan.year,item,mentor:p.mentor,coordinator:plan.coordinator,head:plan.head,due:p.due,roster,taskMappings:p.tasks.map(t=>({id:t.id,mappingVersion:t.mappingVersion||0})),ledger:p.departmentTaskCSVLedger||[]}),controlled:(db.planApprovalRecords||[]).some(r=>r.planId===plan.id||r.planId===plan.family)};
}
function departmentTaskCSVDepartment(p){const s=departmentTaskCSVSource(p);return !!s&&canSee(p)&&[s.plan.coordinator,s.plan.head].includes(uid)}
function departmentTaskCSVReader(p){if(!p||p.sourceClub||p.intakeProvenance||p.teamIntakeProvenance||!['Workshop','Seminar'].includes(p.type)||!canSee(p))return false;const plans=db.plans.filter(x=>x.id===p.sourcePlan),plan=plans.length===1?plans[0]:null;return !!plan&&[plan.coordinator,plan.head,p.mentor].includes(uid)}
function departmentTaskCSVBatch(p,id){return (p?.departmentTaskCSVBatches||[]).find(b=>b.id===id)}
function departmentTaskCSVCurrent(p,b){return !!b&&departmentTaskCSVSource(p)?.basis===b.basis}
function departmentTaskCSVValidate(p,row){
 const errors=[],clean=v=>typeof v==='string'&&v.trim()&&v.length<=2000&&!/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(v);
 if(!/^[A-Z0-9][A-Z0-9_.:-]{0,79}$/.test(row.externalId))errors.push('externalId must be a stable 1–80 character task reference');
 if(!p.members.includes(row.studentReference)||!activeParticipant(p,row.studentReference))errors.push('studentReference is not an active member of this event roster');
 if(row.studentReference===p.mentor)errors.push('The assigned mentor cannot assess their own imported task');
 if(!clean(row.title)||row.title.length>120)errors.push('Task title is required, up to 120 characters');
 for(const key of ['expectedOutput','responsibility','evidenceRequirement'])if(!clean(row[key]))errors.push(key+' is required, up to 2000 characters');
 if(typeof row.groupReference!=='string'||row.groupReference.length>2000||/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(row.groupReference))errors.push('Invalid groupReference');
 if(!validWorkDate(row.due)||row.due>p.due)errors.push('Use a valid task deadline no later than the current event deadline');
 if(!Object.keys(departmentTaskCSVDomains).some(k=>row[k]?.trim()))errors.push('At least one observable domain criterion is required');
 for(const key of Object.keys(departmentTaskCSVDomains))if(row[key]&&!clean(row[key]))errors.push('Invalid '+key);
 return errors;
}
function departmentTaskCSVParse(p,text){
 const rows=academicCSV(text),header=rows.shift();if(!header||header.length!==departmentTaskCSVColumns.length||new Set(header).size!==header.length||departmentTaskCSVColumns.some(k=>!header.includes(k)))throw Error('Use exactly the supplied CSV headers.');
 if(!rows.length||rows.length>50)throw Error('Upload 1–50 task rows per batch.');
 const parsed=rows.map((cells,i)=>({line:i+2,cells,row:Object.fromEntries(header.map((k,j)=>[k,cells[j]||'']))}));const counts=new Map();for(const r of parsed){r.row.externalId=r.row.externalId.toUpperCase();counts.set(r.row.externalId,(counts.get(r.row.externalId)||0)+1)}
 return parsed.map(({line,cells,row})=>{const errors=departmentTaskCSVValidate(p,row);if(cells.length!==header.length)errors.push('Column count differs from the header');if(counts.get(row.externalId)>1)errors.push('Duplicate externalId in this file');const binding=JSON.stringify(Object.fromEntries(departmentTaskCSVColumns.map(k=>[k,row[k]]))),old=(p.departmentTaskCSVLedger||[]).filter(x=>x.externalId===row.externalId);if(old.length>1)errors.push('Existing import ledger needs review');if(old.length&&old[0].binding!==binding)errors.push('This event task reference was imported with different content; existing work will not be overwritten');if(old.length&&!p.tasks.some(t=>t.id===old[0].taskId))errors.push('Previously imported task is missing; reconcile its history first');return {line,row,binding,state:errors.length?'INVALID':old.length?'ALREADY_IMPORTED':'VALID',errors,existingTaskId:old[0]?.taskId||null}});
}
function previewDepartmentTaskCSV(event){
 event.preventDefault();const p=current();if(!departmentTaskCSVDepartment(p))return toast('The responsible department must prepare this class-event import.');const f=Object.fromEntries(new FormData(event.target));if(Object.keys(f).some(k=>!['sourceReference','csv'].includes(k))||typeof f.sourceReference!=='string'||!f.sourceReference.trim()||f.sourceReference.length>100)return toast('Provide a stable source reference.');
 const ref=f.sourceReference.trim(),previous=(p.departmentTaskCSVBatches||[]).filter(b=>b.sourceReference===ref).at(-1);if(previous&&['PREVIEWED','SUBMITTED','MENTOR_APPROVED'].includes(previous.state))return toast('Finish or return the current batch for this source reference first.');
 let rows;try{rows=departmentTaskCSVParse(p,f.csv)}catch(e){return toast(e.message)}
 const source=departmentTaskCSVSource(p),batch={id:clubKey('DCSV'),version:1,state:'PREVIEWED',sourceReference:ref,rows,basis:source.basis,rosterSnapshot:JSON.parse(JSON.stringify(source.roster)),academicPeriod:{programme:source.plan.programme,year:source.plan.year,semester:source.plan.semester,course:source.plan.course,batch:source.plan.batch,sourcePlan:source.plan.id,sourcePlanVersion:source.plan.version},by:uid,at:new Date().toISOString(),corrects:previous?.state==='RETURNED'?previous.id:null,history:[]};
 p.departmentTaskCSVBatches??=[];p.departmentTaskCSVBatches.push(batch);log(p,'Department task CSV preview '+batch.id+'; no tasks assigned');closeModal();render();toast('Preview saved. Correct all invalid rows before requesting mentor review.');
}
function submitDepartmentTaskCSV(id,expectedVersion){const p=current(),b=departmentTaskCSVBatch(p,id);if(!departmentTaskCSVDepartment(p)||!b||b.state!=='PREVIEWED'||b.version!==expectedVersion||!departmentTaskCSVCurrent(p,b)||b.rows.some(r=>r.state==='INVALID')||!b.rows.some(r=>r.state==='VALID'))return toast('Use a current, valid preview with new task rows.');b.state='SUBMITTED';b.version++;b.history.push({action:'SUBMITTED',by:uid,at:new Date().toISOString()});log(p,'Department task CSV sent to assigned mentor '+id);render()}
function reviewDepartmentTaskCSV(event,id,expectedVersion){event.preventDefault();const p=current(),b=departmentTaskCSVBatch(p,id),f=Object.fromEntries(new FormData(event.target));if(!departmentTaskCSVReader(p)||uid!==p.mentor||!b||!['PREVIEWED','SUBMITTED'].includes(b.state)||b.version!==expectedVersion||b.by===uid||Object.keys(f).some(k=>!['decision','reason','confirm'].includes(k))||f.confirm!=='yes'||!['MENTOR_APPROVED','RETURNED'].includes(f.decision)||typeof f.reason!=='string'||!f.reason.trim()||f.reason.length>2000)return toast('Independent assigned-mentor review, current batch, reason and confirmation required.');if(f.decision==='MENTOR_APPROVED'&&(b.state!=='SUBMITTED'||!departmentTaskCSVCurrent(p,b)||b.rows.some(r=>r.state==='INVALID')||b.rows.some(r=>r.state==='VALID'&&r.row.studentReference===uid)))return toast('A current valid submitted batch and independent mentor are required.');b.state=f.decision;b.version++;b.review={by:uid,decision:f.decision,reason:f.reason.trim(),at:new Date().toISOString(),basis:b.basis};b.history.push({action:f.decision,...b.review});log(p,'Department task CSV '+f.decision+' '+id);closeModal();render()}
function returnDepartmentTaskCSV(event,id,expectedVersion){event.preventDefault();const p=current(),b=departmentTaskCSVBatch(p,id),f=Object.fromEntries(new FormData(event.target));if(!departmentTaskCSVDepartment(p)||!b||!['PREVIEWED','SUBMITTED','MENTOR_APPROVED'].includes(b.state)||b.version!==expectedVersion||Object.keys(f).some(k=>!['reason','confirm'].includes(k))||f.confirm!=='yes'||typeof f.reason!=='string'||!f.reason.trim()||f.reason.length>2000)return toast('A current unapplied batch, department reason and confirmation are required.');b.state='RETURNED';b.version++;b.history.push({action:'DEPARTMENT_RETURN',by:uid,reason:f.reason.trim(),at:new Date().toISOString()});log(p,'Department task CSV returned without changing existing tasks '+id);closeModal();render()}
function applyDepartmentTaskCSV(event,id,expectedVersion){
 event.preventDefault();const p=current(),b=departmentTaskCSVBatch(p,id),f=Object.fromEntries(new FormData(event.target));if(!departmentTaskCSVDepartment(p)||!b||Object.keys(f).some(k=>!['reason','confirm'].includes(k))||f.confirm!=='yes'||typeof f.reason!=='string'||!f.reason.trim()||f.reason.length>2000)return toast('Department confirmation and a reason are required.');if(b.state==='APPLIED')return toast('This batch was already applied; no duplicate tasks created.');const s=departmentTaskCSVSource(p);
 if(b.state!=='MENTOR_APPROVED'||b.version!==expectedVersion||!departmentTaskCSVCurrent(p,b)||b.review?.by!==p.mentor||b.review?.decision!=='MENTOR_APPROVED'||b.review?.basis!==b.basis||s.controlled||b.rows.some(r=>r.state==='INVALID'))return toast('Use a current mentor-approved batch. Controlled-plan execution authorization remains separate.');
 const fresh=b.rows.filter(r=>r.state==='VALID');if(!fresh.length||fresh.some(r=>departmentTaskCSVValidate(p,r.row).length||(p.departmentTaskCSVLedger||[]).some(l=>l.externalId===r.row.externalId)))return toast('Source rows or roster changed. Request a fresh preview and mentor review.');
 p.departmentTaskCSVLedger??=[];
 for(const entry of fresh){const r=entry.row,fields={title:r.title,assignee:r.studentReference,due:r.due,expectedOutput:r.expectedOutput,responsibility:r.responsibility,evidenceRequirement:r.evidenceRequirement,groupReference:r.groupReference,reason:f.reason.trim()};for(const [column,domain] of Object.entries(departmentTaskCSVDomains))if(r[column]){fields[domain]='yes';fields['criterion_'+domain]=r[column]}
  const t=recordAuthorizedTaskMapping({preventDefault(){}},-1,true,fields);if(!t||p.tasks.filter(x=>x.id===t.id).length!==1)throw Error('Department task mapping could not be committed atomically.');t.academicPeriod=JSON.parse(JSON.stringify(b.academicPeriod));t.sourceDepartmentTaskCSV={batchId:b.id,externalId:r.externalId,sourceReference:b.sourceReference,departmentBy:uid,mentorReviewedBy:b.review.by};t.workState='ASSIGNED';p.departmentTaskCSVLedger.push({externalId:r.externalId,sourceReference:b.sourceReference,binding:entry.binding,taskId:t.id,batchId:b.id,at:new Date().toISOString()});entry.taskId=t.id;
 }
 b.state='APPLIED';b.version++;b.appliedBy=uid;b.appliedAt=new Date().toISOString();b.history.push({action:'APPLIED',by:uid,at:b.appliedAt,reason:f.reason.trim()});log(p,'Department task CSV applied '+id+'; '+fresh.length+' individual task(s)');closeModal();render();toast('Tasks assigned. Students must submit their own work for separate mentor assessment.');
}
function departmentTaskCSVPanel(p){if(!departmentTaskCSVReader(p))return '';const department=departmentTaskCSVDepartment(p);return `<section class="panel"><h2>Department workshop and seminar tasks</h2><p>Department CSV planning → assigned mentor review → department confirmation → individual tasks. The current event roster is retained; uploads cannot enrol students, approve the event, complete work or award credit.</p><p>Use the exact roster account reference. This owner-controlled demo uses fictional roster records; official MIS class-roster validation remains pending.</p>${department?btn('Upload task CSV / preview','departmentTaskCSVForm()')+btn('Download CSV template','downloadDepartmentTaskCSVTemplate()')+btn('Download current roster references','downloadDepartmentTaskCSVRoster()'):''}${(p.departmentTaskCSVBatches||[]).map(b=>`<div class="card"><h3>${esc(b.sourceReference)} · ${esc(b.state)}</h3><p>${esc(b.id)} · v${b.version} · Prepared by ${esc(name(b.by))}${b.corrects?' · Corrects '+esc(b.corrects):''} · ${b.state==='APPLIED'?'Applied; historical source retained':departmentTaskCSVCurrent(p,b)?'Source current':'Source changed — fresh review required'}</p>${tableHTML(['CSV row / task reference','Student / task','Validation'],b.rows.map(r=>[r.line+' / '+esc(r.row.externalId),esc(name(r.row.studentReference))+' · '+esc(r.row.title)+'<details><summary>Individual instructions and criteria</summary><dl>'+departmentTaskCSVColumns.filter(k=>!['externalId','studentReference','title'].includes(k)).map(k=>'<dt>'+esc(k)+'</dt><dd>'+esc(r.row[k]||'Not selected')+'</dd>').join('')+'</dl></details>',esc(r.state)+(r.errors.length?'<p>'+r.errors.map(esc).join('; ')+'</p>':'')]))}${b.review?`<p>Mentor review: ${esc(name(b.review.by))} · ${esc(b.review.decision)} · ${esc(b.review.reason)}</p>`:''}${department&&b.state==='PREVIEWED'&&departmentTaskCSVCurrent(p,b)&&b.rows.every(r=>r.state!=='INVALID')&&b.rows.some(r=>r.state==='VALID')?btn('Send to mentor',`submitDepartmentTaskCSV('${b.id}',${b.version})`):''}${uid===p.mentor&&departmentTaskCSVSource(p)&&['PREVIEWED','SUBMITTED'].includes(b.state)&&b.by!==uid?btn('Review task batch',`departmentTaskCSVReviewForm('${b.id}')`):''}${department&&b.state==='MENTOR_APPROVED'&&departmentTaskCSVCurrent(p,b)&&!departmentTaskCSVSource(p).controlled?btn('Confirm and create tasks',`departmentTaskCSVApplyForm('${b.id}')`):''}${department&&['PREVIEWED','SUBMITTED','MENTOR_APPROVED'].includes(b.state)?btn('Return / replace this batch',`departmentTaskCSVReturnForm('${b.id}')`):''}<details><summary>Batch history</summary>${b.history.map(h=>`<p>${esc(h.action)} · ${esc(name(h.by))} · ${esc(h.reason||'')} · ${esc(h.at)}</p>`).join('')||'<p>Preview only.</p>'}</details></div>`).join('')}</section>`}
function departmentTaskCSVForm(){const p=current();if(!departmentTaskCSVDepartment(p))return;modal(`<h2>Upload individual event tasks</h2><p>${esc(p.title)} · CSV only · maximum 30 KB / 50 data rows. Use a stable source reference; task references are unique within this event. Re-importing identical rows never overwrites existing tasks.</p><form onsubmit="previewDepartmentTaskCSV(event)"><label>Source reference<input name="sourceReference" required maxlength="100"></label><label>Choose CSV file<input id="department-task-csv-file" type="file" accept=".csv,text/csv" onchange="readDepartmentTaskCSVFile(event)"></label><label>CSV content<textarea id="department-task-csv-text" name="csv" required maxlength="30000"></textarea></label><p>File reading is local. Save the preview to validate roster references, deadlines, evidence and assessment domains. No tasks are created at preview.</p><button type="submit">Validate and save preview</button><button type="button" onclick="closeModal()">Cancel</button></form>`)}
async function readDepartmentTaskCSVFile(event){const input=event.target,file=input.files?.[0],target=document.querySelector('#department-task-csv-text'),project=selected;if(!file||!/\.csv$/i.test(file.name)||file.size>30000)return toast('Choose a CSV file no larger than 30 KB.');try{const text=await file.text();if(selected!==project||document.querySelector('#department-task-csv-text')!==target||!departmentTaskCSVDepartment(current()))return;if(text.length>30000)throw Error('CSV exceeds the import limit.');target.value=text;toast('CSV loaded locally. Validate the preview before requesting review.')}catch{return toast('CSV could not be read. No assignments were made.')}}
function departmentTaskCSVReviewForm(id){const p=current(),b=departmentTaskCSVBatch(p,id);if(!b||uid!==p.mentor)return;modal(`<h2>Assigned mentor task review</h2><form onsubmit="reviewDepartmentTaskCSV(event,'${id}',${b.version})"><label>Decision<select name="decision"><option value="MENTOR_APPROVED">Approve task definitions</option><option value="RETURNED">Return for correction</option></select></label><label>Review reason<textarea name="reason" required maxlength="2000"></textarea></label><label><input type="checkbox" name="confirm" value="yes" required>I reviewed the individual duties, outputs, evidence and assessment criteria. This does not complete or grade student work.</label><button type="submit">Record mentor review</button></form>`)}
function departmentTaskCSVApplyForm(id){const b=departmentTaskCSVBatch(current(),id);if(!b||!departmentTaskCSVDepartment(current()))return;modal(`<h2>Department confirmation</h2><form onsubmit="applyDepartmentTaskCSV(event,'${id}',${b.version})"><label>Assignment reason<textarea name="reason" required maxlength="2000"></textarea></label><label><input type="checkbox" name="confirm" value="yes" required>Create only the mentor-approved new rows as individual tasks. Preserve existing work and the event roster.</label><button type="submit">Create individual tasks</button></form>`)}
function departmentTaskCSVReturnForm(id){const b=departmentTaskCSVBatch(current(),id);if(!b||!departmentTaskCSVDepartment(current()))return;modal(`<h2>Return CSV batch</h2><form onsubmit="returnDepartmentTaskCSV(event,'${id}',${b.version})"><label>Correction / return reason<textarea name="reason" required maxlength="2000"></textarea></label><label><input type="checkbox" name="confirm" value="yes" required>Return this batch without deleting its history or changing existing tasks.</label><button type="submit">Return batch</button></form>`)}
function departmentTaskCSVDownload(rows,filename){const cell=v=>{let s=String(v??'');if(/^[=+\-@\t]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadDepartmentTaskCSVTemplate(){if(!departmentTaskCSVDepartment(current()))return;departmentTaskCSVDownload([departmentTaskCSVColumns],'department-event-task-template.csv')}
function downloadDepartmentTaskCSVRoster(){const p=current();if(!departmentTaskCSVDepartment(p))return;departmentTaskCSVDownload([['studentReference','displayName','active'],...departmentTaskCSVSource(p).roster.map(r=>[r.student,name(r.student),r.active?'YES':'NO'])],'department-event-roster-references.csv')}
const departmentTaskCSVPriorOverview=projectOverview;projectOverview=function(p){return departmentTaskCSVPriorOverview(p)+departmentTaskCSVPanel(p)};
// The same class-event assignment policy applies to manual and CSV entry.
// Student project leads keep their existing task workflow outside this route.
const departmentTaskCSVPriorMappingWritable=taskMappingWritable;
taskMappingWritable=function(p){const source=departmentTaskCSVSource(p);if(source)return !source.controlled&&canSee(p)&&(departmentTaskCSVDepartment(p)||uid===p.mentor);if(p?.sourcePlan&&!p.sourceClub&&!p.intakeProvenance&&!p.teamIntakeProvenance&&['Workshop','Seminar'].includes(p.type))return false;return departmentTaskCSVPriorMappingWritable(p)};
const departmentTaskCSVPriorPlansPage=plansPage;
plansPage=function(){const events=db.projects.filter(p=>departmentTaskCSVReader(p));return departmentTaskCSVPriorPlansPage()+(events.length?`<section class="panel"><h2>Workshop and seminar task assignments</h2><p>Strategic event-plan uploads remain separate. For every departmental class workshop or seminar, the responsible department and assigned mentor control individual task assignment. Use the current event roster; student-project proposals continue through Activity Intake.</p>${events.map(p=>{const s=departmentTaskCSVSource(p);return `<div class="row"><div><strong>${esc(p.title)}</strong><p>${esc(s.plan.course)} · Semester ${esc(s.plan.semester)} · ${s.roster.length} roster reference(s)</p></div>${btn('Open event task planning',`openProject('${p.id}')`)}</div>`}).join('')}<div class="buttons">${academicReader()?btn('Student placement / progression CSV',"go('Academic Progression')"):''}</div><p>Placement import supports known student references. New student-master uploads and official MIS synchronization require their separate controlled integration; event rosters and past task mappings retain their snapshots.</p></section>`:'')};
const departmentTaskCSVPriorSaveMapping=saveTaskMapping;
saveTaskMapping=function(event,index=-1){const p=current(),source=departmentTaskCSVSource(p),priorPeriod=p?.tasks[index]?.academicPeriod,task=departmentTaskCSVPriorSaveMapping(event,index);if(task&&source&&!priorPeriod){task.academicPeriod={programme:source.plan.programme,year:source.plan.year,semester:source.plan.semester,course:source.plan.course,batch:source.plan.batch,sourcePlan:source.plan.id,sourcePlanVersion:source.plan.version};save()}return task};

// Interim owner-demo unit review. Institutional AP-001 approval and execution
// authority remain separate, protected server services, never persona labels.
function clubPlanManaged(c,p){return !!p?.approvalControl?.managed||(db.planApprovalRecords||[]).some(r=>{try{let s=JSON.parse(r.sourceBinding);return s.kind==='CLUB'&&s.content.source.clubId===c.id&&s.id===p.id&&(s.content.source.record.version||1)===(p.version||1)}catch{return false}})}
function clubPlanCurrentUnitReview(c,p){return (p.unitReviewRecords||[]).filter(r=>r.clubId===c.id&&r.planId===p.id&&r.planVersion===(p.version||1)).at(-1)||null}
const clubPlanGovernancePriorState=clubPlanState;
clubPlanState=function(id,pid,next){if(next==='APPROVED')return toast('Student Affairs endorsement is not final approval. Finance Administrator review and Principal approval are required through protected plan review.');return clubPlanGovernancePriorState(id,pid,next)};
function clubPlanUnitReviewWritable(c,p){return !!c&&!!p&&clubOfficer()&&uid!==c.owner&&uid!==p.owner&&p.state==='ADMIN_REVIEW'&&['APPROVED','ACTIVE','RENEWAL_DUE'].includes(c.state)&&!clubPlanManaged(c,p)&&clubItems(p).length>0&&clubItems(p).every(i=>i.status==='CANCELLED'?!!i.cancelReason&&!clubItemActivity(i):validateClubRow(c,i))}
function clubPlanUnitReviewForm(id,pid){const c=clubById(id),p=c&&clubPlan(c,pid);if(!clubPlanUnitReviewWritable(c,p))return toast('An independent Student Affairs unit review is required.');modal(`<h2>Student Affairs plan review</h2><p>Record the unit recommendation and forward this plan for Finance Administrator review and Principal final approval. This action does not approve expenditure or authorize execution.</p><form onsubmit="recordClubPlanUnitReview(event,'${esc(id)}','${esc(pid)}')"><input type="hidden" name="planVersion" value="${p.version||1}"><label>Review reason and recommendation<textarea name="reason" required maxlength="4000"></textarea></label><label style="display:flex;gap:8px;align-items:flex-start"><input style="width:auto;margin-top:3px" type="checkbox" name="confirm" value="yes" required><span>Endorse this exact plan version for further review</span></label><button class="primary">Record endorsement</button> <button type="button" onclick="closeModal()">Cancel</button></form>`)}
function recordClubPlanUnitReview(e,id,pid){e.preventDefault();const c=clubById(id),p=c&&clubPlan(c,pid),f=Object.fromEntries(new FormData(e.target)),reason=String(f.reason||'').trim();if(!clubPlanUnitReviewWritable(c,p)||f.confirm!=='yes'||String(p.version||1)!==f.planVersion||!reason||reason.length>4000||/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(reason))return toast('Use the current version, an independent Student Affairs reviewer, a reason and explicit confirmation.');p.unitReviewRecords??=[];p.unitReviewRecords.push({id:'CUR-'+Date.now()+'-'+p.unitReviewRecords.length,clubId:c.id,planId:p.id,planVersion:p.version||1,action:'ENDORSED',by:uid,at:new Date().toISOString(),reason,authority:'OWNER_DEMO_UNIT_REVIEW',finalApproval:false,executionAuthorized:false});p.state='UNIT_ENDORSED';clubLog(c,'Student Affairs endorsed annual plan '+p.id+' v'+(p.version||1)+'; Finance Administrator and Principal decisions still required.');closeModal();render();toast('Unit endorsement recorded. Final approval and new event authorization are still pending.')}
const clubPlanGovernancePriorReturnForm=clubPlanReturnForm,clubPlanGovernancePriorReturn=returnClubPlan;
clubPlanReturnForm=function(id,pid){const c=clubById(id),p=c&&clubPlan(c,pid);if(p?.state!=='UNIT_ENDORSED')return clubPlanGovernancePriorReturnForm(id,pid);if(!clubOfficer()||uid===c.owner||uid===p.owner||clubPlanManaged(c,p))return;modal(`<h2>Withdraw unit endorsement and return plan</h2><form onsubmit="returnClubPlan(event,'${esc(id)}','${esc(pid)}')"><label>Required changes<textarea name="reason" required maxlength="4000"></textarea></label><button class="primary">Return to draft</button> <button type="button" onclick="closeModal()">Cancel</button></form>`)};
returnClubPlan=function(e,id,pid){const c=clubById(id),p=c&&clubPlan(c,pid);if(p?.state!=='UNIT_ENDORSED')return clubPlanGovernancePriorReturn(e,id,pid);e.preventDefault();const reason=String(new FormData(e.target).get('reason')||'').trim(),review=clubPlanCurrentUnitReview(c,p);if(!clubOfficer()||uid===c.owner||uid===p.owner||clubPlanManaged(c,p)||!review||review.action!=='ENDORSED'||!reason||reason.length>4000)return toast('An independent Student Affairs reviewer and a reason are required.');p.unitReviewRecords.push({id:'CUR-'+Date.now()+'-'+p.unitReviewRecords.length,clubId:c.id,planId:p.id,planVersion:p.version||1,action:'WITHDRAWN',reviewId:review.id,by:uid,at:new Date().toISOString(),reason,authority:'OWNER_DEMO_UNIT_REVIEW',finalApproval:false,executionAuthorized:false});p.state='DRAFT';p.reviewNote=reason;clubLog(c,'Student Affairs returned endorsed plan '+p.id+' for changes; prior unit recommendation retained.');closeModal();render()};
const clubPlanGovernancePriorEvent=clubEvent;
clubEvent=function(id,pid,iid){const c=clubById(id),p=c&&clubPlan(c,pid),i=p&&clubItems(p).find(x=>x.id===(iid||clubItems(p)[0]?.id));if(i&&clubItemActivity(i))return clubPlanGovernancePriorEvent(id,pid,iid);return toast('New club events require protected approval and separate execution authorization. Legacy approval or Student Affairs endorsement alone is insufficient.')};
const clubPlanGovernancePriorCard=clubPlanCard;
clubPlanCard=function(c,p){let html=clubPlanGovernancePriorCard(c,p);const approve=btn('Approve annual plan',`clubPlanState('${c.id}','${p.id}','APPROVED')`,'primary');html=html.replace(approve,clubPlanUnitReviewWritable(c,p)?btn('Review and endorse plan',`clubPlanUnitReviewForm('${c.id}','${p.id}')`,'primary'):'');for(const i of clubItems(p))if(!clubItemActivity(i))html=html.replace(btn('Create event',`clubEvent('${c.id}','${p.id}','${i.id}')`,'primary'),'<span class="meta">Protected execution authorization pending</span>');let review=clubPlanCurrentUnitReview(c,p);return html+`<div class="notice"><strong>Plan authority:</strong> mentor review → Student Affairs unit review → Finance Administrator → Principal. New execution needs a separate authorization.${p.state==='UNIT_ENDORSED'?' Unit endorsement is recorded; final decisions are pending.':''}${isApprovedClubPlan(p)?' This retained legacy approval status is historical evidence; it does not establish the full approval chain for new execution.':''}</div>`+(review?`<details><summary>Student Affairs unit review history</summary>${(p.unitReviewRecords||[]).filter(r=>r.clubId===c.id&&r.planId===p.id&&r.planVersion===(p.version||1)).map(r=>`<p><strong>${esc(label(r.action))}</strong> · ${esc(name(r.by))} · ${esc(eventTime(r.at))}<br>${esc(r.reason)}</p>`).join('')}<p class="meta">Owner-demo unit records; no institutional final approval, payment or execution authority.</p></details>`:'')+(p.state==='UNIT_ENDORSED'&&clubOfficer()&&uid!==c.owner&&uid!==p.owner&&!clubPlanManaged(c,p)?btn('Return endorsed plan for revision',`clubPlanReturnForm('${c.id}','${p.id}')`):'')};
const clubPlanGovernancePriorPage=clubsPage;
clubsPage=function(){return clubPlanGovernancePriorPage().replace('annual plan receives mentor and Student Affairs approval → Student Affairs activates the club. Club Finance supports budget approval and settlement.','annual plan receives mentor and Student Affairs unit review, then protected Finance Administrator review and Principal final approval. Club formation, plan approval, execution authorization and financial settlement remain distinct. Legacy statuses do not prove this complete chain.')};

// Departmental source records for shared M30 planning. No new roles, scoring,
// placement offers, plan approvals or execution authority are created here.
const studentAffairsServiceAreas=Object.freeze({CLUB_EVENTS:'Club events and leadership',PLACEMENT_CAREER:'Placement and career services',INTERNSHIPS:'Internship coordination',LEADERSHIP_SKILLS:'Leadership, skills and student development',COMMUNITY_PARTNERSHIPS:'Community, SDG and partnership activities',PARTICIPATION_RECOGNITION:'Participation, recognition and follow-up'});
function studentAffairsPlanner(){return uid==='sa1'}
function studentAffairsUnitPlan(id){return (db.unitPlans||[]).find(p=>p.id===id&&p.unitCode==='STUDENT_AFFAIRS')}
function studentAffairsPlanControlled(p){return !!p?.approvalControl?.managed||(db.planApprovalRecords||[]).some(r=>{try{const s=JSON.parse(r.sourceBinding);return s.kind==='DEPARTMENTAL'&&s.id===p.id&&s.version===(p.version||1)&&s.content.source.record.id===p.id}catch{return false}})}
function studentAffairsDraftWritable(p){return studentAffairsPlanner()&&p?.owner===uid&&p.state==='DRAFT'&&!studentAffairsPlanControlled(p)}
function studentAffairsPlanLog(p,action){const r={time:new Date().toISOString(),actor:name(uid),action,project:p.id};p.history??=[];p.history.unshift(r);db.audit.unshift(r);save()}
function studentAffairsPlanForm(id){const p=id?studentAffairsUnitPlan(id):null;if(!studentAffairsPlanner()||(id&&!studentAffairsDraftWritable(p)))return;modal(`<h2>${p?'Edit':'Create'} Student Affairs department plan</h2><form onsubmit="saveStudentAffairsPlan(event,'${esc(id||'')}')">${field('title','Plan title',p?.title||'')}${field('cycle','Planning cycle',p?.cycle||'')}<label>Department objectives<textarea name="objectives" required maxlength="4000">${esc(p?.objectives||'')}</textarea></label><p>Draft plans receive no approval or execution authority. Programme areas share the protected responsible-unit → Finance Administrator → Principal plan review.</p><button class="primary">Save draft</button> <button type="button" onclick="closeModal()">Cancel</button></form>`)}
function saveStudentAffairsPlan(e,id){e.preventDefault();const p=id?studentAffairsUnitPlan(id):null,f=Object.fromEntries(new FormData(e.target));if(!studentAffairsPlanner()||(id&&!studentAffairsDraftWritable(p))||!String(f.title||'').trim()||f.title.length>200||!String(f.cycle||'').trim()||f.cycle.length>80||!String(f.objectives||'').trim()||f.objectives.length>4000)return toast('Use a writable draft and complete the title, cycle and objectives.');let plan=p;if(!plan){const key=clubKey('UP');plan={id:key,family:key,version:1,unitCode:'STUDENT_AFFAIRS',owner:uid,kind:'DEPARTMENTAL',state:'DRAFT',title:f.title.trim(),cycle:f.cycle.trim(),objectives:f.objectives.trim(),items:[],history:[]};db.unitPlans??=[];db.unitPlans.push(plan)}else Object.assign(plan,{title:f.title.trim(),cycle:f.cycle.trim(),objectives:f.objectives.trim()});studentAffairsPlanLog(plan,'Department plan draft saved; institutional review and execution are separate.');closeModal();render()}
function studentAffairsItemForm(planId,itemId){const p=studentAffairsUnitPlan(planId),i=p?.items.find(x=>x.id===itemId);if(!studentAffairsDraftWritable(p))return;modal(`<h2>${i?'Edit':'Add'} service programme / activity</h2><form onsubmit="saveStudentAffairsPlanItem(event,'${esc(planId)}','${esc(itemId||'')}')"><label>Service area<select name="serviceArea">${Object.entries(studentAffairsServiceAreas).map(([k,v])=>`<option value="${k}" ${i?.serviceArea===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label>${field('title','Programme / activity',i?.title||'')}${field('start','Start date',i?.start||'','date')}${field('end','End date',i?.end||'','date')}${field('responsible','Responsible person',i?.responsible||'')}${field('mentorEvaluator','Mentor / evaluator arrangement',i?.mentorEvaluator||'')}<label>Expected deliverable<textarea name="deliverable" required maxlength="2000">${esc(i?.deliverable||'')}</textarea></label>${field('kpi','KPI / measure',i?.kpi||'')}${field('target','Target',i?.target||'')}${field('budget','Planned budget (NPR)',i?.budget||'0')}${field('budgetReference','Budget / funding reference',i?.budgetReference||'')}<label>Evidence required<textarea name="evidence" required maxlength="2000">${esc(i?.evidence||'')}</textarea></label><p>Names and arrangements in this plan are planning declarations. They do not create an assignment, evaluator permission, placement selection or payment authority.</p><button class="primary">Save planned item</button> <button type="button" onclick="closeModal()">Cancel</button></form>`)}
function studentAffairsItemValid(i){return !!i&&Object.hasOwn(studentAffairsServiceAreas,i.serviceArea)&&['title','responsible','mentorEvaluator','deliverable','kpi','target','budgetReference','evidence'].every(k=>typeof i[k]==='string'&&i[k].trim()&&i[k].length<=(['deliverable','evidence'].includes(k)?2000:200))&&typeof i.start==='string'&&typeof i.end==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(i.start)&&/^\d{4}-\d{2}-\d{2}$/.test(i.end)&&Number.isFinite(Date.parse(i.start))&&Number.isFinite(Date.parse(i.end))&&new Date(i.start).toISOString().slice(0,10)===i.start&&new Date(i.end).toISOString().slice(0,10)===i.end&&i.start<=i.end&&/^\d+(?:\.\d{1,2})?$/.test(i.budget)&&Number.isSafeInteger(Math.round(Number(i.budget)*100))}
function saveStudentAffairsPlanItem(e,planId,itemId){e.preventDefault();const p=studentAffairsUnitPlan(planId),i=p?.items.find(x=>x.id===itemId),f=Object.fromEntries(new FormData(e.target));if(!studentAffairsDraftWritable(p)||(itemId&&!i))return toast('Only the current draft owner can change planned items.');for(const k of Object.keys(f))f[k]=f[k].trim();if(!studentAffairsItemValid(f))return toast('Complete the service area, dates, responsibilities, targets, budget reference and evidence requirements.');if(i)Object.assign(i,f);else p.items.push({id:clubKey('UPI'),...f});studentAffairsPlanLog(p,'Department service plan item '+(i?'updated':'added')+'; no execution or evaluator assignment created.');closeModal();render()}
function submitStudentAffairsPlan(e,id){e.preventDefault();const p=studentAffairsUnitPlan(id),f=Object.fromEntries(new FormData(e.target));if(!studentAffairsDraftWritable(p)||String(p.version)!==f.planVersion||f.confirm!=='yes'||!String(f.reason||'').trim()||f.reason.length>4000||!p.items.length||p.items.some(i=>!studentAffairsItemValid(i)))return toast('Confirm the current complete plan version with a submission reason.');p.state='SUBMITTED';p.submission={by:uid,at:new Date().toISOString(),reason:f.reason.trim(),planVersion:p.version};p.submissionRecords??=[];p.submissionRecords.push({...p.submission,action:'SUBMITTED'});studentAffairsPlanLog(p,'Department plan submitted for protected review; no approval, payment or execution authority granted.');closeModal();render()}
function studentAffairsSubmitForm(id){const p=studentAffairsUnitPlan(id);if(!studentAffairsDraftWritable(p))return;modal(`<h2>Submit department plan for review</h2><form onsubmit="submitStudentAffairsPlan(event,'${esc(id)}')"><input name="planVersion" type="hidden" value="${p.version}"><label>Submission reason<textarea name="reason" required maxlength="4000"></textarea></label><label style="display:flex;gap:8px"><input style="width:auto" name="confirm" type="checkbox" value="yes" required><span>Submit this exact version for the protected review route</span></label><p>Responsible-unit review → Finance Administrator → Principal. Named institutional source/reviewer mappings must be active before protected decisions can be recorded.</p><button class="primary">Submit for review</button> <button type="button" onclick="closeModal()">Cancel</button></form>`)}
function withdrawStudentAffairsPlanSubmission(e,id){e.preventDefault();const p=studentAffairsUnitPlan(id),f=Object.fromEntries(new FormData(e.target)),reason=String(f.reason||'').trim();if(!studentAffairsPlanner()||p?.owner!==uid||p.state!=='SUBMITTED'||studentAffairsPlanControlled(p)||String(p.version)!==f.planVersion||!reason||reason.length>4000||f.confirm!=='yes')return toast('Only an unlocked current submission may be withdrawn with a reason.');p.submissionRecords??=[];p.submissionRecords.push({action:'WITHDRAWN',by:uid,at:new Date().toISOString(),reason,planVersion:p.version});p.state='DRAFT';studentAffairsPlanLog(p,'Department submission withdrawn for draft correction; earlier submission retained.');closeModal();render()}
function studentAffairsWithdrawForm(id){const p=studentAffairsUnitPlan(id);if(!studentAffairsPlanner()||p?.owner!==uid||p.state!=='SUBMITTED'||studentAffairsPlanControlled(p))return;modal(`<h2>Withdraw pending department submission</h2><form onsubmit="withdrawStudentAffairsPlanSubmission(event,'${esc(id)}')"><input name="planVersion" type="hidden" value="${p.version}"><label>Reason<textarea name="reason" required maxlength="4000"></textarea></label><label><input style="width:auto" type="checkbox" name="confirm" value="yes" required>Return this unlocked version to draft for correction</label><p>Once protected institutional review starts, use that review's return/amendment route instead.</p><button class="primary">Withdraw submission</button></form>`)}
// Called by the server view before private intake/project filtering. Never grants case access.
function studentAffairsInternshipProjection(){
 if(!studentAffairsPlanner())return null;
 const counts={submittedIntakes:0,withdrawnIntakes:0,currentApprovedPlacements:0,currentApproachLetters:0,currentStartAuthorizations:0,executionWorkspaces:0,currentExecutionSources:0,changedExecutionSources:0,pausedOrCancelledWorkspaces:0,currentApprovedFinalReviews:0,unclassifiableRecords:0};
 const intakes=(db.activityIntakes||[]).filter(r=>r?.content?.type==='Internship'&&r.state!=='DRAFT'&&Array.isArray(r.submissions)&&r.submissions.length>0);
 for(const r of intakes){counts.submittedIntakes++;if(r.state==='WITHDRAWN'){counts.withdrawnIntakes++;continue}try{const placement=internshipLatest(r),readiness=internshipReadinessLatest(r);if(placement?.state==='APPROVED'&&internshipCurrent(r,placement))counts.currentApprovedPlacements++;if(internshipCurrentLetter(r))counts.currentApproachLetters++;if(readiness?.state==='START_AUTHORIZED'&&internshipReadinessCurrent(r,readiness))counts.currentStartAuthorizations++}catch{counts.unclassifiableRecords++}}
 for(const p of db.projects||[]){if(!p?.internshipProvenance)continue;counts.executionWorkspaces++;try{const current=internshipProjectCurrent(p);if(current)counts.currentExecutionSources++;else counts.changedExecutionSources++;if(!activityControlActive(p))counts.pausedOrCancelledWorkspaces++;if(current&&activityControlActive(p)&&internshipFinalApproved(p))counts.currentApprovedFinalReviews++}catch{counts.unclassifiableRecords++}}
 return {available:true,schema:'KCC360_SA_INTERNSHIP_SUMMARY_V1',scope:'OWNER_DEMO',counts,basis:'Submitted owner-demo internship intakes and linked execution workspaces. Counts overlap across stages; withdrawn intakes are excluded from current authorization counts. No eligible-cohort denominator, employment outcome, grade or academic credit is inferred.'};
}
function studentAffairsInternshipFacts(){return studentAffairsPlanner()&&db.studentAffairsInternshipSummary?.schema==='KCC360_SA_INTERNSHIP_SUMMARY_V1'?db.studentAffairsInternshipSummary:{available:false,reason:'The server internship summary is unavailable for this session.'}}
function studentAffairsInternshipPanel(){const summary=studentAffairsInternshipFacts();if(!summary.available)return '<section class="panel"><h2>Internship coordination</h2><p>Unavailable — '+esc(summary.reason)+'</p></section>';const c=summary.counts;return '<section class="panel" style="margin:20px 0"><h2>Internship coordination — workflow facts</h2>'+tableHTML(['Measure','Count'],[['Submitted intakes (including withdrawn)',c.submittedIntakes],['Withdrawn intakes',c.withdrawnIntakes],['Current approved placement proposals',c.currentApprovedPlacements],['Current approach letters',c.currentApproachLetters],['Current start authorizations',c.currentStartAuthorizations],['Linked execution workspaces',c.executionWorkspaces],['Execution workspaces with current sources',c.currentExecutionSources],['Execution workspaces with changed sources',c.changedExecutionSources],['Paused or cancelled execution workspaces',c.pausedOrCancelledWorkspaces],['Current independently approved final reviews',c.currentApprovedFinalReviews],['Records requiring classification review',c.unclassifiableRecords]].map(([label,count])=>[label,String(count)]))+'<p class="meta">'+esc(summary.basis)+'</p><p>Approach letters do not establish host acceptance or permission to start. Final reviews do not award grades or credit. Case records retain their existing permissions; this summary creates no case access or decision authority.</p></section>'}
function studentAffairsMonitoringFacts(){if(!studentAffairsPlanner())return null;const clubIds=new Set((db.clubs||[]).map(c=>c.id)),activities=db.projects.filter(p=>p.sourceClub&&clubIds.has(p.sourceClub)&&canSee(p)),waiting=activities.flatMap(p=>(p.members||[]).filter(id=>p.reflections?.[id]&&!p.evaluations?.[id]?.final)),clubEvaluations=(db.clubEvaluations||[]).filter(r=>clubEvaluationReader(clubById(r.clubId)));return {clubActivities:activities.length,verifiedClubActivities:activities.filter(verifiedActivity).length,openClubActivities:activities.filter(p=>!verifiedActivity(p)&&p.activityControl?.state!=='CANCELLED').length,awaitingIndividualEvaluation:waiting.length,annualEvaluationsAwaitingUnitReview:clubEvaluations.filter(r=>r.state==='SUBMITTED').length,placement:{available:false,reason:'The job-placement case workflow is not yet available.'},internships:studentAffairsInternshipFacts(),basis:'Existing readable owner-demo club records only; no whole-college placement or eligible-cohort denominator.'}}
function studentAffairsApprovedCalendarPanel(){if(!studentAffairsPlanner())return '';const calendar=db.studentAffairsApprovedCalendar;if(calendar?.schema!=='KCC360_APPROVED_CLUB_CALENDAR_V1')return '<section class="panel"><h2>Approved club activity calendar</h2><p>Unavailable — refresh the shared workspace to load the server calendar.</p></section>';return '<section class="panel" style="margin:20px 0"><h2>Approved club activity calendar</h2><p>Names and dates appear here after responsible-unit review, Finance Administrator review and Principal final approval.</p>'+ (calendar.events.length?tableHTML(['Club / annual cycle','Approved activity','Dates','Plan version / status'],calendar.events.map(i=>[esc(i.clubName)+'<br>'+esc(i.cycle),esc(i.title),esc(i.start)+' → '+esc(i.end),esc(i.planId)+' · v'+i.planVersion+'<br>Approved planning entry'])):'<p>No finally approved protected club activities are available. Drafts, unit endorsements and legacy approval labels are excluded. Institutional review configuration remains required.</p>')+'<p class="meta">'+esc(calendar.basis)+'</p>'+(calendar.withheldPlans?'<p class="notice">'+calendar.withheldPlans+' plan source(s) require reconciliation; their activities are withheld.</p>':'')+'</section>'}
function studentAffairsReviewLink(p){const query=new URLSearchParams({planId:p.id,planVersion:String(p.version)});return `<a class="button" href="/workspace/plan-approvals.html?${esc(query.toString())}" target="_blank" rel="noopener">Open protected plan review</a>`}
function studentAffairsPage(){if(!studentAffairsPlanner())return heading('Student Affairs','Department planning is outside the current demo role.')+'<div class="notice">Use an authorized departmental assignment. Selecting a page grants no permission.</div>';const plans=(db.unitPlans||[]).filter(p=>p.unitCode==='STUDENT_AFFAIRS'),facts=studentAffairsMonitoringFacts();return heading('Student Affairs department','Plan, monitor and review the departmental service portfolio.',btn('+ Department plan','studentAffairsPlanForm()','primary'))+`<div class="notice">Department plans and club plans use responsible-unit review → Finance Administrator → Principal. Draft or submitted targets do not authorize events, placements, payments or individual evaluation. This workspace remains an owner-only demonstration.</div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(240px,1fr))">${Object.entries(studentAffairsServiceAreas).map(([k,label])=>{const items=plans.flatMap(p=>p.items.filter(i=>i.serviceArea===k));return `<div class="card"><h3>${esc(label)}</h3><p>${items.length} planned item${items.length===1?'':'s'} across the department plans shown below.</p><p class="meta">Planning entries include draft/submitted work; this is not a completed-service count.</p></div>`}).join('')}</div><section class="panel" style="margin:20px 0"><h2>Monitoring — available facts</h2>${tableHTML(['Measure','Value / status'],[['Readable club activities',String(facts.clubActivities)],['Verified club activities',String(facts.verifiedClubActivities)],['Open club activities',String(facts.openClubActivities)],['Submitted reflections awaiting final evaluation',String(facts.awaitingIndividualEvaluation)],['Annual club evaluations awaiting unit review',String(facts.annualEvaluationsAwaitingUnitReview)],['Job placement outcomes','Unavailable — '+esc(facts.placement.reason)],['Institution-wide internship outcomes','Unavailable — no official eligible-cohort denominator or MIS outcome reconciliation.']])}<p class="meta">${esc(facts.basis)} Counts show workflow facts, not a performance rating or an individual student score.</p><div class="buttons">${btn('Club workspaces',"go('Clubs')")}${btn('Annual evaluation',"go('Club Evaluation')")}${btn('Existing authorized reports',"go('Reports')")}</div></section>${studentAffairsInternshipPanel()}${studentAffairsApprovedCalendarPanel()}${plans.map(p=>`<section class="panel" style="margin:20px 0"><div class="top"><div><h2>${esc(p.title)}</h2><p>${esc(p.cycle)} · ${esc(p.id)} · v${p.version}</p></div>${pill(p.state)}</div><p>${esc(p.objectives)}</p><p class="meta">Owner: ${esc(name(p.owner))} · ${studentAffairsPlanControlled(p)?'Protected source locked; generic edits disabled.':'Preparation/submission status only; protected approval decisions are separate.'}</p>${p.approvalControl?.reviewState?'<p>Protected review: '+esc(label(p.approvalControl.reviewState))+' · New execution is not authorized.</p>':''}<div class="buttons">${studentAffairsDraftWritable(p)?btn('Edit plan',`studentAffairsPlanForm('${p.id}')`)+btn('+ Service item',`studentAffairsItemForm('${p.id}')`)+btn('Submit for review',`studentAffairsSubmitForm('${p.id}')`,'primary'):''}${p.state==='SUBMITTED'&&!studentAffairsPlanControlled(p)?btn('Withdraw for correction',`studentAffairsWithdrawForm('${p.id}')`):''}${studentAffairsReviewLink(p)}</div>${tableHTML(['Service / planned activity','Dates / responsibility','Deliverable / KPI / target','Budget reference','Evidence / arrangement','Action'],p.items.map(i=>[esc(studentAffairsServiceAreas[i.serviceArea])+'<br><strong>'+esc(i.title)+'</strong>',esc(i.start)+' → '+esc(i.end)+'<br>'+esc(i.responsible),esc(i.deliverable)+'<br>'+esc(i.kpi)+' · '+esc(i.target),'NPR '+esc(i.budget)+'<br>'+esc(i.budgetReference),esc(i.evidence)+'<br>'+esc(i.mentorEvaluator),studentAffairsDraftWritable(p)?btn('Edit',`studentAffairsItemForm('${p.id}','${i.id}')`):'Locked']))}<details><summary>Plan preparation history</summary>${history(p.history||[])}</details></section>`).join('')||'<div class="panel">No department plans have been created. Add a plan and service items; the system does not prepopulate targets or actual outcomes.</div>'}`}
